#include <bits/stdc++.h>
using namespace std;
using P=array<uint8_t,9>;
const int F[10]={1,1,2,6,24,120,720,5040,40320,362880};
int rankp(const P&a){int k=0;for(int i=0;i<9;i++){int less=0;for(int j=i+1;j<9;j++)less+=(a[j]<a[i]);k+=less*F[8-i];}return k;}
vector<vector<int>> parts;
void partrec(int rem,int prev,vector<int> cur){if(rem==0){parts.push_back(cur);return;}for(int x=prev;x<=rem;x++) if(x>=2){auto c=cur;c.push_back(x);partrec(rem-x,x,c);}}
P inv(const P&p){P q;for(int i=0;i<9;i++)q[p[i]]=i;return q;}
P conj(const P&g,const P&p,const P&pi){P h;for(int i=0;i<9;i++)h[i]=pi[g[p[i]]];return h;}
int main(){ofstream reps("E064_ordered_representatives.jsonl");partrec(9,2,{});vector<tuple<vector<int>,long long,long long,long long>> output;long long total=0;for(auto part:parts){P f;vector<vector<int>> cycles;int base=0;for(int len:part){vector<int> cy;for(int i=0;i<len;i++)cy.push_back(base+i);for(int i=0;i<len;i++)f[base+i]=base+(i+1)%len;base+=len;cycles.push_back(cy);}vector<P> gs;for(auto &cy:cycles){P p; iota(p.begin(),p.end(),0);for(int k=0;k<(int)cy.size();k++)p[cy[k]]=cy[(k+1)%cy.size()];gs.push_back(p);}for(int i=0;i+1<(int)cycles.size();i++){if(cycles[i].size()==cycles[i+1].size()){P p;iota(p.begin(),p.end(),0);for(int j=0;j<(int)cycles[i].size();j++)swap(p[cycles[i][j]],p[cycles[i+1][j]]);gs.push_back(p);}}vector<P> gis;for(auto p:gs)gis.push_back(inv(p));vector<uint8_t> visited(362880,0);P g; iota(g.begin(),g.end(),0);long long admiss=0,orbits=0,orbit_sum=0;int maxsz=0;do{bool ok=true;for(int i=0;i<9;i++)if(g[i]==i||g[i]==f[i]){ok=false;break;}if(!ok)continue;admiss++;int id=rankp(g);if(visited[id])continue;orbits++;reps<<"{\"type\":[";for(size_t ti=0;ti<part.size();ti++){if(ti)reps<<",";reps<<part[ti];}reps<<"],\"f\":[";for(int ti=0;ti<9;ti++){if(ti)reps<<",";reps<<int(f[ti]);}reps<<"],\"g\":[";for(int ti=0;ti<9;ti++){if(ti)reps<<",";reps<<int(g[ti]);}reps<<"]}\n";vector<P> st;st.push_back(g);visited[id]=1;for(size_t a=0;a<st.size();a++){for(int b=0;b<(int)gs.size();b++){P q=conj(st[a],gs[b],gis[b]);int h=rankp(q);if(!visited[h]){visited[h]=1;st.push_back(q);}}}orbit_sum+=st.size();maxsz=max(maxsz,(int)st.size());}while(next_permutation(g.begin(),g.end()));if(admiss!=orbit_sum){cerr<<"NOT PRESERVED";return 1;}long long cent=1;for(auto&c:cycles)cent*=c.size();int last=0;for(int x:part){if(x!=last){int count=std::count(part.begin(),part.end(),x);for(int k=1;k<=count;k++)cent*=k;last=x;}}total+=orbits;output.push_back({part,cent,admiss,orbits});cout<<"{\"type\":[";for(size_t i=0;i<part.size();i++){if(i)cout<<",";cout<<part[i];}cout<<"],\"centralizer\":"<<cent<<",\"allowed_g\":"<<admiss<<",\"g_orbits\":"<<orbits<<",\"max_orbit\":"<<maxsz<<"}\n";}cout<<"TOTAL "<<total<<"\n";
}